import React, { useRef } from 'react';
import { Image, TouchableOpacity, View } from 'react-native';
import { BottomSheet, BottomSheetManager, BottomSheetRef, RadioButton, Text } from '@core/ui';
import useCSS from '@src/presentation/style';
import { useDispatch, useSelector } from '@src/lib/redux';
import { selectAccount, selectCurrentAccounts, selectDepositRateMethodDesc, selectIsCounter, selectLoanPurpose, selectPaymentAcct } from '../selector';
import slice from '../slice';
import { CURRENCY } from '@src/utils/constants';
import { formatMoney } from '@src/utils/currency';
import { ICurrentAccount } from '@src/domain/entities/loan_collateral/get_list_current_accounts';
import { IAccount } from '@src/domain/entities/loan_collateral/depositAccount';
import type { LoanPurpose as ILoanPurpose } from '@src/domain/entities/loan_collateral/get_init_loan_proposal';
import getImg from '@src/utils/getImg';
import { useTranslation } from 'react-i18next';

const SectionInfoDetail = () => {
    const css = useCSS();
    const dispatch = useDispatch();
    const { t } = useTranslation(['module_collateral']);

    const account = useSelector<IAccount>(selectAccount);
    const loanPurpose = useSelector<ILoanPurpose>(selectLoanPurpose);
    const refBSAccount = useRef<BottomSheetRef>(null);
    const currentAccounts = useSelector<ICurrentAccount[]>(selectCurrentAccounts);
    const paymentAcct = useSelector<string>(selectPaymentAcct);
    const depositRateMethodDesc = useSelector<string>(selectDepositRateMethodDesc);
    const isCounter = useSelector<boolean>(selectIsCounter);

    const handleSelected = (accountNo: string) => {
        dispatch(slice.actions.setPaymentAcct(accountNo));
        refBSAccount.current?.close();
    };

    return (
        <View style={[]}>
            <View style={[css.row, css.items_center, css.pv_regular]}>
                <Text style={[css.w_40pc, css.text_subheadline, css.text_neutral_600, css.font_regular]}>{t('screen_confirm.payment_acct')}</Text>
                <View style={[css.w_60pc]}>
                    <TouchableOpacity
                        disabled={!isCounter}
                        onPress={() => {
                            BottomSheetManager.show({
                                render: (portalId) => (
                                    <BottomSheet ref={refBSAccount} id={portalId} title={t('screen_confirm.bs_title_payment_acct')}>
                                        {currentAccounts?.map((item, index) => (
                                            <React.Fragment key={`key-${item.accountNo}-${index}`}>
                                                {index > 0 ? <View style={[css.border_t_1, css.border_t_neutral_300]} /> : null}
                                                <TouchableOpacity style={[css.p_base]} onPress={() => handleSelected(item?.accountNo)}>
                                                    <View style={[css.row, css.items_center]}>
                                                        <Image
                                                            source={getImg('/assets/images/avatar_hdbank.png')}
                                                            style={[css.w_xxxLarge, css.ratio_square, css.rounded_full, css.shrink_0, css.mr_regular]}
                                                        />
                                                        <View style={[css.flex_1]}>
                                                            <Text style={[css.text_caption_100, css.text_neutral_700, css.font_regular]}>
                                                                {item?.accountNo}
                                                            </Text>
                                                            <Text style={[css.text_body, css.font_regular]}>
                                                                {formatMoney(Number(item?.availableBalance))} {CURRENCY}
                                                            </Text>
                                                        </View>
                                                        <RadioButton text='' onPress={() => undefined} size='large' checked={item?.accountNo === paymentAcct} />
                                                    </View>
                                                </TouchableOpacity>
                                            </React.Fragment>
                                        ))}
                                    </BottomSheet>
                                ),
                            });
                        }}>
                        <View style={[css.row, css.items_center, css.justify_end]}>
                            <Text numberOfLines={1} style={[css.flex_1, css.text_subheadline, css.font_semibold, css.text_right, css.ml_base]}>
                                {paymentAcct}
                            </Text>
                            {isCounter ? (
                                <Image
                                    source={getImg('/assets/images/icons/right_arrow.png')}
                                    resizeMode='contain'
                                    style={[css.w_regular, css.ratio_square, css.ml_base]}
                                />
                            ) : null}
                        </View>
                    </TouchableOpacity>
                </View>
            </View>
            <View style={[css.border_t_1, css.border_t_neutral_300]} />
            <View style={[css.row, css.items_center, css.pv_regular]}>
                <Text style={[css.flex_1, css.text_subheadline, css.text_neutral_600, css.font_regular]}>{t('screen_confirm.savings_book')}</Text>
                <View style={[css.flex_1, css.ml_base]}>
                    <Text style={[css.text_subheadline, css.font_semibold, css.text_right]}>{account?.accountNo}</Text>
                    <Text style={[css.text_caption_100, css.text_neutral_600, css.text_right, css.font_regular]}>
                        {formatMoney(account?.balance)} {CURRENCY}
                    </Text>
                </View>
            </View>
            <View style={[css.border_t_1, css.border_t_neutral_300]} />
            <View style={[css.row, css.items_center, css.pv_regular]}>
                <Text style={[css.flex_1, css.text_subheadline, css.text_neutral_600, css.font_regular]}>{t('screen_confirm.loan_purpose_name')}</Text>
                <Text style={[css.flex_1, css.text_subheadline, css.font_semibold, css.text_right, css.ml_base]}>{loanPurpose?.loanPurposeName}</Text>
            </View>
            <View style={[css.border_t_1, css.border_t_neutral_300]} />
            <View style={[css.row, css.items_center, css.pv_regular]}>
                <Text style={[css.flex_1, css.text_subheadline, css.text_neutral_600, css.font_regular]}>{t('screen_confirm.deposit_rate_method_desc')}</Text>
                <Text style={[css.flex_1, css.text_subheadline, css.font_semibold, css.text_right, css.ml_base]}>{depositRateMethodDesc}</Text>
            </View>
        </View>
    );
};

export default SectionInfoDetail;
