import { View, Text, FlatList, TouchableOpacity } from 'react-native'
import React, { useEffect, useRef, useState } from 'react'
import { BottomSheet, BottomSheetManager, createStyles, RadioButton, useTheme, Theme, BottomSheetRef } from '@core/ui';
import { registerStaticData } from '@src/domain/entities/cms/loan_register/registerStaticData';
import SelectOption from '../selectOption';

type listSelectedProps = {
    title: string;
    fn: () => void;
}
type BottomSheetRadioListProps = {
    show: boolean;
    title: string;
    listOption: registerStaticData[] | undefined;
    onClose?: () => void;
    onSelected?: (data: registerStaticData) => void;
}
export default function BottomSheetRadioList(Props: BottomSheetRadioListProps) {
    const { theme } = useTheme()
    const styles = useStyles();
    const bsRef = useRef<BottomSheetRef>(null);
    const onShowModal = () => {
        BottomSheetManager.show({
            render: (portalId) => (
                <BottomSheet ref={bsRef} id={portalId} title={Props.title} description='' onClose={Props.onClose} >
                    {<SelectOption listOption={Props.listOption} onSelected={handleRadioPress} />}
                </BottomSheet>
            ),
        });
    };


    const handleRadioPress = (data: registerStaticData) => {
        Props.onSelected?.(data);
        bsRef.current?.close();
    };
    useEffect(() => {
        if (Props.show) {
            onShowModal()
        }
    }, [Props.show]);
    return (
        <View>
        </View>
    )
}


const useStyles = createStyles((theme: Theme) => ({
    container: {
        paddingVertical: theme.Size.Vertical.Medium,
    },
    row: {
        flexDirection: 'row',
        justifyContent: 'space-between',
        alignItems: 'center',
        paddingVertical: theme.Size.vs(10),
    },
    label: {
        ...theme.Typography.TextBody.Regular,
    },
}));
