import uuid from 'react-native-uuid';
import { injectable } from 'inversify';
import { HttpService } from '@core/service';
import type { ResendOTPPayload } from '@src/application/loan_collateral/queries/resend_otp/resend_otp_query';
import { BASE_URL_LOAN_API } from '@src/config';
import { ResendOTPResponse } from '@src/domain/entities/loan_collateral/resend_otp';
import type { IResendOTPRepository } from '@src/domain/interfaces/loan_collateral/resend_otp';
import { commonService } from '@src/infrastructure/network/networkService';

@injectable()
export class ResendOTPRepository extends HttpService implements IResendOTPRepository {
    constructor() {
        super({ baseURL: BASE_URL_LOAN_API });
    }
    async resendOTP(query: ResendOTPPayload): Promise<ResendOTPResponse> {
        const request = query as unknown as ResendOTPPayload;
        const url = '/resendOTP';
        const dataReq = {
            ...request,
            requestId: uuid.v4(),
        };

        const { data } = await this.post(url, dataReq, {
            headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-loan-collateral' }),
        });
        return data as ResendOTPResponse;
    }
}
